// ============================================================
// ➕ Teilnehmer zu bestehender Registrierung hinzufügen
//    ➜ Startnummer automatisch fortsetzen
// ============================================================
exports.addParticipant = async (req, res) => {
    const t = await EventRegistrationParticipant.sequelize.transaction();

    try {
        const {
            registration_id,
            person_id,
            squadron_id,
            participation_type,
            catering_type,
            gender,
            staffel_aufnahme,
        } = req.body;

        if (!registration_id || !person_id) {
            return res.status(400).json({
                message: "registration_id und person_id sind erforderlich.",
            });
        }

        const registration = await EventRegistration.findByPk(registration_id, {
            transaction: t,
        });

        if (!registration) {
            return res.status(404).json({
                message: "Registrierung nicht gefunden.",
            });
        }

        const event_id = registration.event_id;

        const normalizedParticipationType = participation_type ?? "einzeln";
        const normalizedSquadronId = normalizedParticipationType === "staffel"
            ? (squadron_id ?? null)
            : null;

        const startNumber = await assignParticipantStartNumber({
            event_id,
            participation_type: normalizedParticipationType,
            squadron_id: normalizedSquadronId,
            transaction: t,
        });

        const participant = await EventRegistrationParticipant.create(
            {
                registration_id,
                person_id,
                squadron_id: normalizedSquadronId,
                participation_type: normalizedParticipationType,
                catering_type: catering_type ?? null,
                gender: gender ?? null,
                staffel_aufnahme: staffel_aufnahme ?? null,
                start_number: startNumber,
            },
            { transaction: t }
        );

        await t.commit();
        res.status(201).json(participant);
    } catch (err) {
        await t.rollback();
        console.error("❌ Fehler beim Hinzufügen eines Teilnehmers:", err);
        res.status(500).json({
            message: "Fehler beim Hinzufügen eines Teilnehmers.",
        });
    }
};


// ============================================================
// ✏️ Startnummer eines Teilnehmers ändern (Admin)
// ============================================================
exports.updateParticipantStartNumber = async (req, res) => {
    try {
        const { participantId } = req.params;
        const { start_number } = req.body;

        let newStartNumber = null;

        if (start_number === null || start_number === undefined || start_number === "") {
            return res.status(400).json({
                message: "start_number ist verpflichtend und muss eine positive Ganzzahl sein.",
            });
        }

        const parsed = Number(start_number);
        if (!Number.isInteger(parsed) || parsed < 1) {
            return res.status(400).json({
                message: "start_number ist verpflichtend und muss eine positive Ganzzahl sein.",
            });
        }

        newStartNumber = parsed;

        const participant = await EventRegistrationParticipant.findByPk(participantId, {
            include: [
                {
                    model: EventRegistration,
                    as: "registration",
                    attributes: ["event_id"],
                },
            ],
        });

        if (!participant) {
            return res.status(404).json({ message: "Teilnehmer nicht gefunden." });
        }

        const eventId = participant.registration?.event_id;

        if (eventId) {
            const existing = await EventRegistrationParticipant.findOne({
                where: { start_number: newStartNumber },
                include: [
                    {
                        model: EventRegistration,
                        as: "registration",
                        where: { event_id: eventId },
                        attributes: [],
                    },
                ],
            });

            const isSameSquadronUpdate =
                !!participant.squadron_id &&
                !!existing?.squadron_id &&
                existing.squadron_id === participant.squadron_id;

            if (existing && existing.id !== participant.id && !isSameSquadronUpdate) {
                return res.status(409).json({
                    message: `Startnummer ${newStartNumber} ist für dieses Event bereits vergeben.`,
                });
            }
        }

        if (participant.participation_type === "staffel" && participant.squadron_id) {
            await EventRegistrationParticipant.update(
                { start_number: newStartNumber },
                { where: { squadron_id: participant.squadron_id } }
            );

            await Squadron.update(
                { start_number: String(newStartNumber) },
                { where: { id: participant.squadron_id } }
            );
        } else {
            await participant.update({ start_number: newStartNumber });
        }

        res.json({
            message: "Startnummer erfolgreich aktualisiert.",
            participant: await EventRegistrationParticipant.findByPk(participantId),
        });
    } catch (err) {
        console.error("❌ Fehler beim Aktualisieren der Startnummer:", err);
        res.status(500).json({
            message: "Fehler beim Aktualisieren der Startnummer.",
        });
    }
};


// ============================================================
//  Registrierungen nach Person (Ersteller)
// ============================================================
exports.getRegistrationsByPerson = async (req, res) => {
    try {
        const { personId } = req.params;

        const regs = await EventRegistration.findAll({
            where: {
                registered_by_person_id: personId,
            },
            include: [
                {
                    model: Event,
                    as: "event",
                },
                {
                    model: EventRegistrationParticipant,
                    as: "participants",
                },
            ],
            order: [["createdAt", "DESC"]],
        });

        res.json(regs);
    } catch (err) {
        console.error("❌ Fehler beim Laden der Registrierungen der Person:", err);
        res.status(500).json({
            message: "Fehler beim Laden der Registrierungen der Person.",
        });
    }
};


// ============================================================
// ️ Registrierung löschen
// ============================================================
exports.deleteRegistration = async (req, res) => {
    try {
        const reg = await EventRegistration.findByPk(req.params.id);
        if (!reg) {
            return res.status(404).json({ message: "Anmeldung nicht gefunden." });
        }

        await reg.destroy();
        res.json({ message: "Anmeldung erfolgreich gelöscht." });
    } catch (err) {
        console.error("❌ Fehler beim Löschen der Anmeldung:", err);
        res.status(500).json({ message: "Fehler beim Löschen der Anmeldung." });
    }
};

module.exports = {
  async up(queryInterface, Sequelize) {
    const transaction = await queryInterface.sequelize.transaction();

    try {
      const [participants] = await queryInterface.sequelize.query(
        `
          SELECT
            p.id,
            p.registration_id,
            p.squadron_id,
            p.participation_type,
            p.start_number,
            r.event_id,
            p.createdAt
          FROM event_registration_participant p
          INNER JOIN event_registration r ON r.id = p.registration_id
          ORDER BY r.event_id ASC, p.createdAt ASC
        `,
        { transaction }
      );

      const nextNumberByEvent = new Map();
      const squadronNumberByKey = new Map();

      for (const participant of participants) {
        const eventId = participant.event_id;
        const currentStartNumber = Number(participant.start_number);

        const currentMax = nextNumberByEvent.get(eventId) ?? 1;
        if (Number.isInteger(currentStartNumber) && currentStartNumber >= currentMax) {
          nextNumberByEvent.set(eventId, currentStartNumber + 1);
        }
      }

      for (const participant of participants) {
        const eventId = participant.event_id;
        let assignedStartNumber = Number(participant.start_number);

        if (participant.participation_type === 'staffel' && participant.squadron_id) {
          const squadronKey = `${eventId}:${participant.squadron_id}`;

          if (!squadronNumberByKey.has(squadronKey)) {
            if (!Number.isInteger(assignedStartNumber) || assignedStartNumber < 1) {
              assignedStartNumber = nextNumberByEvent.get(eventId) ?? 1;
              nextNumberByEvent.set(eventId, assignedStartNumber + 1);
            }
            squadronNumberByKey.set(squadronKey, assignedStartNumber);
          }

          assignedStartNumber = squadronNumberByKey.get(squadronKey);

          await queryInterface.sequelize.query(
            `UPDATE squadron SET start_number = :startNumber WHERE id = :squadronId`,
            {
              replacements: {
                startNumber: String(assignedStartNumber),
                squadronId: participant.squadron_id,
              },
              transaction,
            }
          );
        } else {
          if (!Number.isInteger(assignedStartNumber) || assignedStartNumber < 1) {
            assignedStartNumber = nextNumberByEvent.get(eventId) ?? 1;
            nextNumberByEvent.set(eventId, assignedStartNumber + 1);
          }
        }

        await queryInterface.sequelize.query(
          `UPDATE event_registration_participant SET start_number = :startNumber WHERE id = :participantId`,
          {
            replacements: {
              startNumber: assignedStartNumber,
              participantId: participant.id,
            },
            transaction,
          }
        );
      }

      await queryInterface.changeColumn(
        'event_registration_participant',
        'start_number',
        {
          type: Sequelize.INTEGER,
          allowNull: false,
        },
        { transaction }
      );

      await transaction.commit();
    } catch (error) {
      await transaction.rollback();
      throw error;
    }
  },

  async down(queryInterface, Sequelize) {
    await queryInterface.changeColumn('event_registration_participant', 'start_number', {
      type: Sequelize.INTEGER,
      allowNull: true,
    });
  },
};

const { DataTypes } = require("sequelize");
const sequelize = require("../config/db");

const EventRegistrationParticipant = sequelize.define(
    "event_registration_participant",
    {
        id: {
            type: DataTypes.UUID,
            primaryKey: true,
            defaultValue: DataTypes.UUIDV4,
        },

        //  Zugehörige Registrierung
        registration_id: {
            type: DataTypes.UUID,
            allowNull: false,
        },

        //  Person
        person_id: {
            type: DataTypes.UUID,
            allowNull: false,
        },

        //  Staffel (optional)
        squadron_id: {
            type: DataTypes.UUID,
            allowNull: true,
        },

        //  Teilnahme-Art (neu)
        participation_type: {
            type: DataTypes.ENUM('einzeln', 'staffel'),
            allowNull: false,
            defaultValue: 'einzeln',
            comment: 'Teilnahme als Einzelstarter oder in Staffel',
        },

        // ️ Verpflegung (neu)
        catering_type: {
            type: DataTypes.ENUM('vegan', 'vegetarisch'),
            allowNull: true, // null = keine Verpflegung
            comment: 'Verpflegungsart pro Teilnehmer (null = keine)',
        },

        // ️ Startnummer (neu, automatisch)
        start_number: {
            type: DataTypes.INTEGER,
            allowNull: true,
            comment: 'Automatisch vergebene Startnummer pro Event',
        },
    },
    {
        tableName: "event_registration_participant",
        timestamps: true,
        comment: "Teilnehmer einer Event-Registrierung (Person pro Event)",
    }
);

